import{_ as n,C as r,c as l,o as h,ag as a,G as s,w as o,j as t}from"./chunks/framework.DZ_cNctr.js";const k=JSON.parse(`{"title":"Two Lines of HTML to View Microscopy Data on Any Web Page","description":"When text, images, and segmentation results live on the same page, the reader doesn't just read about the science — they see it. Here's how an embeddable OME-ZARR viewer brings context to microscopy data.","frontmatter":{"title":"Two Lines of HTML to View Microscopy Data on Any Web Page","description":"When text, images, and segmentation results live on the same page, the reader doesn't just read about the science — they see it. Here's how an embeddable OME-ZARR viewer brings context to microscopy data.","date":"2026-03-28T00:00:00.000Z","author":"Find Nuclei"},"headers":[],"relativePath":"blog/embeddable-viewer-for-journals.md","filePath":"blog/embeddable-viewer-for-journals.md"}`),d={name:"blog/embeddable-viewer-for-journals.md"};function c(p,e,u,g,m,b){const i=r("ClientOnly");return h(),l("div",null,[e[3]||(e[3]=a('<h1 id="two-lines-of-html-to-view-microscopy-data-on-any-web-page" tabindex="-1">Two Lines of HTML to View Microscopy Data on Any Web Page <a class="header-anchor" href="#two-lines-of-html-to-view-microscopy-data-on-any-web-page" aria-label="Permalink to &quot;Two Lines of HTML to View Microscopy Data on Any Web Page&quot;">​</a></h1><p style="color:var(--vp-c-text-2);font-size:0.9em;">March 28, 2026 · Find Nuclei</p><p>The browser-based OME-ZARR viewing problem is largely solved. Multi-resolution tile rendering, chunked streaming, GPU-accelerated display — the open-source ecosystem handles all of it.</p><p>But every existing solution assumes one thing: the viewer is the page.</p><p>A paper describes a segmentation method. The reader sees a JPEG thumbnail. They can&#39;t scroll the Z-stack to check whether the segmentation holds deeper in the volume, toggle the label overlay, or adjust contrast to see what compression threw away. A LIMS shows a table of acquired images — click a row, open a separate application. A data repository lists a dataset with a thumbnail and metadata fields; to know if it&#39;s relevant, you download gigabytes first.</p><p>In every case, the data and the context describing it live in different places. The reader has to bridge that gap themselves.</p><p>Find Nuclei Viewer embeds. Two lines of HTML, and the viewer is inside your paper, your LIMS, your repository — wherever the text already is.</p><h2 id="what-if-the-image-was-just-there" tabindex="-1">What if the image was just… there? <a class="header-anchor" href="#what-if-the-image-was-just-there" aria-label="Permalink to &quot;What if the image was just… there?&quot;">​</a></h2><p>Here&#39;s what it looks like when a paragraph about nuclear segmentation includes the actual segmentation. This is data from <a href="https://doi.org/10.1371/journal.pbio.3000095" target="_blank" rel="noreferrer">Blin et al. (2019)</a>, published as <a href="https://idr.openmicroscopy.org/study/idr0062/" target="_blank" rel="noreferrer">IDR-0062</a> — confocal microscopy of mouse tissue with automated 3D nuclear detection. Two channels: LaminB1 (nuclear envelope, blue) and DAPI (DNA, yellow). The colored overlay is the segmentation result — each detected nucleus gets a unique color.</p>',9)),s(i,null,{default:o(()=>[...e[0]||(e[0]=[t("div",{style:{"border-radius":"8px",overflow:"hidden",margin:"1rem 0"}},[t("find-nuclei-viewer",{url:"https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0062A/6001240.zarr",labels:"on",width:"100%",height:"400"})],-1)])]),_:1}),e[4]||(e[4]=a('<p>That&#39;s a live viewer. Drag to pan, scroll to zoom. The slider at the bottom scrubs through 236 Z-slices — scroll through them and watch the segmentation follow each nucleus through the volume. Click the colored dot next to &quot;Labels&quot; to toggle the overlay off and see just the fluorescence signal. Click a channel name to change its color. Drag the intensity sliders to reveal dim structures.</p><p>The paragraph described the experiment. The viewer shows it. You don&#39;t navigate away — you verify inline.</p><h2 id="the-author-controls-the-starting-point" tabindex="-1">The author controls the starting point <a class="header-anchor" href="#the-author-controls-the-starting-point" aria-label="Permalink to &quot;The author controls the starting point&quot;">​</a></h2><p>When the paragraph discusses a specific region, the viewer should open there. The <code>x</code>, <code>y</code>, and <code>zoom</code> attributes set the initial view, and <code>channels</code> controls which channels are visible and how they&#39;re displayed.</p><p>This is data from <a href="https://doi.org/10.1016/j.cell.2018.09.031" target="_blank" rel="noreferrer">McDole et al. (2018)</a>, published as <a href="https://idr.openmicroscopy.org/study/idr0079/" target="_blank" rel="noreferrer">IDR-0079</a> — live imaging of zebrafish heart regeneration. Two fluorescent markers: lynEGFP (cell membranes, green) and NLStdTomato (nuclei, red).</p>',5)),s(i,null,{default:o(()=>[...e[1]||(e[1]=[t("div",{style:{"border-radius":"8px",overflow:"hidden",margin:"1rem 0"}},[t("find-nuclei-viewer",{url:"https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0079A/idr0079_images.zarr",channels:"0:on:00FF00:8:90,1:on:FF0000:7:80",x:"500",y:"350",zoom:"-0.5",labels:"on",width:"100%",height:"380"})],-1)])]),_:1}),e[5]||(e[5]=a('<p>The viewer opens at the center of the embryo with both channels and labels enabled — exactly what the surrounding text discusses. But you&#39;re not locked to this view. Pan to adjacent tissue, turn off the green channel to isolate the nuclear signal, or zoom in to check single-cell resolution. The starting view is a suggestion, not a constraint.</p><h2 id="results-alongside-the-evidence" tabindex="-1">Results alongside the evidence <a class="header-anchor" href="#results-alongside-the-evidence" aria-label="Permalink to &quot;Results alongside the evidence&quot;">​</a></h2><p>The combination becomes powerful when quantitative results appear next to the image that produced them. Imagine a LIMS screen or an internal report showing:</p><blockquote><p><strong>Well A3, Field 0</strong> — 847 cells detected, mean nuclear area 142 µm², 12% EdU-positive</p></blockquote><p>With an embedded viewer right below showing that exact field with the segmentation overlay. You don&#39;t need to context-switch to a separate application to check whether &quot;847 cells&quot; looks right. Scroll through the Z-stack, inspect the label boundaries at the edges of the field, and decide whether to trust the count.</p><p>This is equally relevant for data repositories. Consider <a href="https://idr.openmicroscopy.org/study/idr0073/" target="_blank" rel="noreferrer">IDR-0073</a> — <a href="https://doi.org/10.1371/journal.pcbi.1007385" target="_blank" rel="noreferrer">Schaadt et al. (2020)</a>, bright-field histology of human tissue showing tertiary lymphoid organs. An RGB image where the visitor wants to check tissue quality before downloading the full dataset:</p>',6)),s(i,null,{default:o(()=>[...e[2]||(e[2]=[t("div",{style:{"border-radius":"8px",overflow:"hidden",margin:"1rem 0"}},[t("find-nuclei-viewer",{url:"https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0073A/9798462.zarr",background:"white",width:"100%",height:"350"})],-1)])]),_:1}),e[6]||(e[6]=a(`<p>The viewer detects the RGB color model automatically and adjusts the interface — white background, unified brightness slider instead of per-channel controls.</p><h2 id="where-does-this-make-sense" tabindex="-1">Where does this make sense? <a class="header-anchor" href="#where-does-this-make-sense" aria-label="Permalink to &quot;Where does this make sense?&quot;">​</a></h2><p>Anywhere text discusses microscopy data and the reader would benefit from seeing it:</p><p><strong>Journal articles and preprints.</strong> Figures become interactive. The reviewer scrolls through the Z-stack, the reader adjusts contrast, the student explores the raw data behind a publication. Works in any web-based article page — PubPub (eLife), society journal websites, preprint servers.</p><p><strong>LIMS and instrument software.</strong> The image file stops being a filename in a database table. It becomes a preview that loads inline when you click a sample. The LIMS developer adds one script tag and points the viewer at their existing ZARR storage.</p><p><strong>Data repositories.</strong> IDR, BioStudies, EMPIAR, institutional archives. The dataset landing page shows the actual data, not just metadata. Visitors evaluate before downloading.</p><p><strong>Core facility websites.</strong> Example acquisitions from each microscope, properly contrasted with segmentation overlays, demonstrate what the instrument can do better than a spec sheet.</p><p><strong>Internal wikis and documentation.</strong> A staining protocol shows the expected result as an interactive image. New lab members see the real phenotype — and they can toggle channels to understand which marker produces which signal.</p><p><strong>Teaching.</strong> Course pages include real Z-stacks from published datasets. Students navigate the same data the paper analyzed — not a screenshot, the actual volume.</p><h2 id="what-the-reader-can-do" tabindex="-1">What the reader can do <a class="header-anchor" href="#what-the-reader-can-do" aria-label="Permalink to &quot;What the reader can do&quot;">​</a></h2><p>The controls are deliberately focused. Enough to evaluate an image, not so many that the article page turns into a software application:</p><ul><li><strong>Pan and zoom</strong> — navigate the full-resolution image</li><li><strong>Toggle channels</strong> — click the colored dot to show/hide each channel</li><li><strong>Change colors</strong> — click the channel name to pick from 12 scientific color presets (including colorblind-friendly options like cyan and magenta)</li><li><strong>Adjust intensity</strong> — dual-thumb sliders for min/max per channel</li><li><strong>Z-slices</strong> — scrub through 3D volumes</li><li><strong>Timepoints</strong> — step through time series</li><li><strong>Segmentation labels</strong> — toggle overlays on/off, adjust opacity</li><li><strong>Fullscreen</strong> — expand for detailed inspection</li><li><strong>&quot;Open in Find Nuclei Viewer&quot;</strong> — continue in the full app for annotations, Z-projections, and export</li></ul><h2 id="how-to-embed" tabindex="-1">How to embed <a class="header-anchor" href="#how-to-embed" aria-label="Permalink to &quot;How to embed&quot;">​</a></h2><p>Two lines. The first loads the viewer script (once per page). The second places the viewer:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://find-nuclei.github.io/embed/v1/viewer.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">find-nuclei-viewer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0062A/6001240.zarr&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;on&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;100%&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;500&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">find-nuclei-viewer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Every attribute except <code>url</code> is optional. The viewer reads channel names, colors, and intensity ranges from the OME-ZARR metadata. Override whatever you need: initial position (<code>x</code>, <code>y</code>, <code>zoom</code>), channel settings (<code>channels</code>), labels (<code>labels=&quot;on&quot;</code>), background color (<code>background=&quot;white&quot;</code> for brightfield).</p><p>Multiple viewers on the same page work independently. They&#39;re lazy-loaded — data isn&#39;t fetched until the viewer scrolls into view — so a long article with many embedded figures doesn&#39;t slow down the initial page load.</p><p>The full attribute reference is in the <a href="/docs/guides/embedding.html">Embedding Guide</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>This is a v1 release. The embed URL is versioned (<code>/v1/</code>) so existing embeds won&#39;t break when we ship updates.</p><p>We&#39;re working on:</p><ul><li><strong>Shape annotation overlays</strong> — display regions of interest, measurement markups, and pathologist annotations directly on the embedded image</li><li><strong>Linked measurements</strong> — show per-object quantification (area, intensity, shape) as tooltips or a table that highlights objects in the viewer when clicked</li><li><strong>Static preview mode</strong> — render a thumbnail that expands to interactive on click, for pages with many figures</li></ul><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><ul><li><strong><a href="https://find-nuclei.github.io/publications.html" target="_blank" rel="noreferrer">Publications Demo</a></strong> — four IDR studies embedded as interactive viewers</li><li><strong><a href="/docs/guides/embedding.html">Embedding Guide</a></strong> — full attribute reference, live examples, code snippets</li></ul><p>The embed is free. If you&#39;re building a LIMS, data portal, or publication platform and want to integrate it, we&#39;d like to hear about your use case — <a href="mailto:info@find-nuclei.com" target="_blank" rel="noreferrer">info@find-nuclei.com</a>.</p><p style="text-align:center;margin-top:2em;"><a href="https://find-nuclei.github.io/publications.html" target="_blank" rel="noopener noreferrer" style="display:inline-block;padding:0.75em 2em;background:var(--vp-c-brand-1);color:white;border-radius:8px;text-decoration:none;font-weight:600;">See the Publications Demo →</a></p>`,26))])}const f=n(d,[["render",c]]);export{k as __pageData,f as default};
